def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    my = [h[0] for h in history]

    opp_c = 0
    for a in opp:
        if a == 'C':
            opp_c += 1
    opp_d = n - opp_c
    my_c = 0
    for a in my:
        if a == 'C':
            my_c += 1
    my_d = n - my_c

    last_my = my[n - 1]
    last_opp = opp[n - 1]
    rounds_left = 100 - n

    # Count how often the opponent retaliates right after our defection.
    my_def_opps = 0
    opp_retal = 0
    opp_coop_after_my_d = 0
    for i in range(1, n):
        if my[i - 1] == 'D':
            my_def_opps += 1
            if opp[i] == 'D':
                opp_retal += 1
            else:
                opp_coop_after_my_d += 1

    # Opponent never defected: mostly cooperate, then exploit the endgame
    # because they have shown no capacity or willingness to retaliate.
    if opp_d == 0:
        if rounds_left <= 4:
            return 'D'
        return 'C'

    # Opponent defects almost always: defect, with rare probes.
    if opp_d >= n - 1 and n >= 4:
        if rng.random() < 0.04:
            return 'C'
        return 'D'

    # Recent window analysis.
    w = 10 if n >= 10 else n
    recent_opp_d = 0
    recent_my_d = 0
    i = n - w
    while i < n:
        if opp[i] == 'D':
            recent_opp_d += 1
        if my[i] == 'D':
            recent_my_d += 1
        i += 1
    recent_opp_c = w - recent_opp_d

    overall_rate = opp_c / n

    # Opponent is very cooperative overall: stay cooperative, test rarely,
    # and exploit the very end if the opponent does not retaliate.
    if overall_rate >= 0.85:
        if n >= 6 and n % 19 == 0 and rounds_left > 8 and my_d < 2:
            return 'D'
        if rounds_left <= 3:
            if my_def_opps == 0 or opp_retal * 3 <= my_def_opps:
                return 'D'
        return 'C'

    # Opponent is very uncooperative: punish hard but occasionally probe.
    if overall_rate <= 0.2:
        if rounds_left <= 2:
            return 'D'
        if last_opp == 'C' and rng.random() < 0.7:
            return 'C'
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    # If opponent is retaliatory (responds to our defections with defection),
    # avoid unnecessary defection and try to keep mutual cooperation going.
    retaliatory = my_def_opps >= 1 and opp_retal * 2 >= my_def_opps

    # Detect a defection streak by the opponent.
    opp_streak = 0
    i = n - 1
    while i >= 0 and opp[i] == 'D':
        opp_streak += 1
        i -= 1

    # Detect our own defection streak.
    my_streak = 0
    i = n - 1
    while i >= 0 and my[i] == 'D':
        my_streak += 1
        i -= 1

    # If the opponent has been cooperative recently, reciprocate cooperation.
    if recent_opp_c >= w - 1:
        if rounds_left <= 3:
            if my_def_opps == 0 or opp_retal * 3 <= my_def_opps:
                return 'D'
        return 'C'

    # If the opponent defected on our cooperation, retaliate, but do not
    # get stuck in an endless retaliation cycle against a mostly cooperative
    # opponent.
    if last_opp == 'D':
        if last_my == 'C':
            if opp_streak >= 2:
                return 'D'
            if rng.random() < 0.85:
                return 'D'
            return 'C'
        # Both defected last round: try to break the loop if opponent is
        # generally cooperative or retaliatory.
        if my_streak >= 2:
            if overall_rate >= 0.5 or retaliatory:
                if rng.random() < 0.7:
                    return 'C'
            if rng.random() < 0.25:
                return 'C'
        return 'D'

    # Opponent cooperated last round.
    if last_my == 'D':
        # We defected and they cooperated. If they are forgiving, we could
        # exploit, but only when they are not retaliatory and when there is
        # enough time left to repair the relationship.
        if not retaliatory and rounds_left > 6 and overall_rate >= 0.5:
            if rng.random() < 0.35:
                return 'D'
        return 'C'

    # Mutual cooperation: keep it going, with rare late-game testing.
    if recent_opp_d <= 1 and recent_my_d <= 1:
        if rounds_left <= 2:
            if my_def_opps == 0 or opp_retal * 3 <= my_def_opps:
                return 'D'
        if n >= 10 and n % 23 == 0 and rounds_left > 5 and not retaliatory:
            if rng.random() < 0.25:
                return 'D'
        return 'C'

    # Middle ground: cooperate if opponent is mostly cooperative, otherwise
    # lean toward defection.
    if recent_opp_d >= 5:
        return 'D'
    if recent_opp_d >= 3:
        if last_opp == 'D':
            return 'D'
        if rng.random() < 0.6:
            return 'D'
        return 'C'
    if overall_rate >= 0.5:
        return 'C'
    if last_opp == 'C':
        return 'C'
    return 'D'
